const fs = require("fs");
const path = require("path");

const CHANGELOG_PAGE_DOCS = ["sources/postgres", "sources/hubspot"];
const MAX_ROWS_PER_PAGE = 200;
const GENERATED_MARKER =
  "Generated by docusaurus/src/scripts/connector-changelog-pages.js";
const INTEGRATIONS_DOCS = path.resolve(__dirname, "../../../docs/integrations");
const VERSION_PATTERN = /^v?(\d+)\.(\d+)\.(\d+)(?:[-+][0-9A-Za-z.-]+)?$/;

function getSourcePath(docId) {
  if (!CHANGELOG_PAGE_DOCS.includes(docId)) {
    throw new Error(`Unsupported connector changelog document: ${docId}`);
  }

  return path.join(INTEGRATIONS_DOCS, `${docId}.md`);
}

function isGeneratedChangelogPage(filePath) {
  const normalizedPath = String(filePath).replace(/\\/g, "/");
  const fileName = normalizedPath.slice(normalizedPath.lastIndexOf("/") + 1);
  return CHANGELOG_PAGE_DOCS.some(
    (docId) =>
      normalizedPath.endsWith(`/integrations/${docId}/${fileName}`) &&
      /^changelog(?:-[^/]+)?\.md$/i.test(fileName),
  );
}

function getChangelogSourceDocId(filePath) {
  const normalizedPath = String(filePath).replace(/\\/g, "/");
  const fileName = normalizedPath.slice(normalizedPath.lastIndexOf("/") + 1);
  return (
    CHANGELOG_PAGE_DOCS.find(
      (docId) =>
        normalizedPath.endsWith(`/integrations/${docId}.md`) ||
        (normalizedPath.endsWith(`/integrations/${docId}/${fileName}`) &&
          /^changelog(?:-[^/]+)?\.md$/i.test(fileName)),
    ) ?? null
  );
}

function parseVersion(row) {
  const firstCell = row.match(/^\|\s*([^|]+)\|/);
  const version = firstCell?.[1].trim();
  if (!version) return null;
  const match = version?.match(VERSION_PATTERN);

  if (!match) {
    throw new Error(`Could not parse changelog version from row: ${row}`);
  }

  return {
    value: version.replace(/^v/, ""),
    major: Number(match[1]),
    minor: Number(match[2]),
    patch: Number(match[3]),
  };
}

function parseChangelog(source) {
  const lines = source.split(/\r?\n/);
  const changelogHeadingIndex = lines.findIndex((line) =>
    /^##\s+changelog\s*$/i.test(line),
  );

  if (changelogHeadingIndex === -1) {
    throw new Error("Could not find the level-two Changelog heading.");
  }

  let sectionEnd = lines.length;
  for (
    let index = changelogHeadingIndex + 1;
    index < lines.length;
    index += 1
  ) {
    if (/^##\s/.test(lines[index])) {
      sectionEnd = index;
      break;
    }
  }

  const tableStart = lines.findIndex(
    (line, index) =>
      index > changelogHeadingIndex &&
      index < sectionEnd &&
      /^\s*\|/.test(line),
  );
  if (tableStart === -1 || !/^\s*\|/.test(lines[tableStart + 1] || "")) {
    throw new Error("Could not find the Changelog table header and delimiter.");
  }

  const tableHeader = lines.slice(tableStart, tableStart + 2);
  const rowLines = [];
  for (let index = tableStart + 2; index < sectionEnd; index += 1) {
    if (!/^\s*\|/.test(lines[index])) {
      break;
    }
    rowLines.push(lines[index]);
  }

  if (rowLines.length === 0) {
    throw new Error("The Changelog table does not contain any data rows.");
  }

  const parsedVersions = rowLines.map(parseVersion);
  const rows = rowLines.map((line, index) => {
    const version =
      parsedVersions[index] ??
      [...parsedVersions.slice(0, index)].reverse().find(Boolean) ??
      parsedVersions.slice(index + 1).find(Boolean);
    if (!version) {
      throw new Error(`Could not assign a version to changelog row: ${line}`);
    }
    return {
      line,
      version,
      inferredVersion: parsedVersions[index] === null,
    };
  });

  return { lines, tableHeader, rows };
}

function formatMajorRange(majors) {
  const low = Math.min(...majors);
  const high = Math.max(...majors);
  return {
    rangeLabel:
      low === high ? `versions ${low}.x` : `versions ${low}.x–${high}.x`,
    slugPart: low === high ? `v${low}` : `v${low}-v${high}`,
  };
}

function formatMinorRange(major, minors) {
  const low = Math.min(...minors);
  const high = Math.max(...minors);
  return {
    rangeLabel:
      low === high
        ? `versions ${major}.${low}.x`
        : `versions ${major}.${low}–${major}.${high}`,
    slugPart:
      low === high ? `v${major}.${low}` : `v${major}.${low}-v${major}.${high}`,
  };
}

function formatRowRange(rows, chunkNumber) {
  const versions = rows.map((row) => row.version);
  const low = versions.reduce((left, right) =>
    compareVersions(left, right) <= 0 ? left : right,
  );
  const high = versions.reduce((left, right) =>
    compareVersions(left, right) >= 0 ? left : right,
  );
  const lowValue = low.value.replace(/\+/g, "-");
  const highValue = high.value.replace(/\+/g, "-");
  const range = lowValue === highValue ? lowValue : `${lowValue}–${highValue}`;

  return {
    rangeLabel: `versions ${range}`,
    slugPart:
      lowValue === highValue
        ? `v${lowValue}-part-${chunkNumber}`
        : `v${lowValue}-v${highValue}`,
  };
}

function compareVersions(left, right) {
  return (
    left.major - right.major ||
    left.minor - right.minor ||
    left.patch - right.patch ||
    left.value.localeCompare(right.value)
  );
}

function makeGroup(rows, range) {
  return {
    rows: [...rows].sort((left, right) => left.index - right.index),
    ...range,
  };
}

function groupMinorRows(rows, major) {
  const minors = [...new Set(rows.map((row) => row.version.minor))].sort(
    (left, right) => left - right,
  );
  const groups = [];
  let pending = [];
  let pendingMinors = [];
  let chunkNumber = 0;

  const flushPending = () => {
    if (pending.length === 0) return;
    groups.push(makeGroup(pending, formatMinorRange(major, pendingMinors)));
    pending = [];
    pendingMinors = [];
  };

  for (const minor of minors) {
    const minorRows = rows.filter((row) => row.version.minor === minor);
    if (minorRows.length > MAX_ROWS_PER_PAGE) {
      flushPending();
      const oldestFirst = [...minorRows].reverse();
      for (
        let start = 0;
        start < oldestFirst.length;
        start += MAX_ROWS_PER_PAGE
      ) {
        chunkNumber += 1;
        const chunk = oldestFirst.slice(start, start + MAX_ROWS_PER_PAGE);
        groups.push(
          makeGroup([...chunk].reverse(), formatRowRange(chunk, chunkNumber)),
        );
      }
      continue;
    }

    if (pending.length + minorRows.length > MAX_ROWS_PER_PAGE) {
      flushPending();
    }
    pending.push(...minorRows);
    pendingMinors.push(minor);
  }

  flushPending();
  return groups;
}

function groupRows(rows) {
  const indexedRows = rows.map((row, index) => ({ ...row, index }));
  const majors = [...new Set(indexedRows.map((row) => row.version.major))].sort(
    (left, right) => left - right,
  );
  const groups = [];
  let pendingMajors = [];
  let pendingRows = [];

  const flushPending = () => {
    if (pendingRows.length === 0) return;
    groups.push(makeGroup(pendingRows, formatMajorRange(pendingMajors)));
    groups[groups.length - 1].majors = [...pendingMajors];
    pendingMajors = [];
    pendingRows = [];
  };

  for (const major of majors) {
    const majorRows = indexedRows.filter((row) => row.version.major === major);

    if (majorRows.length > MAX_ROWS_PER_PAGE) {
      flushPending();
      groups.push(...groupMinorRows(majorRows, major));
      continue;
    }

    if (pendingRows.length + majorRows.length > MAX_ROWS_PER_PAGE) {
      flushPending();
    }
    pendingMajors.push(major);
    pendingRows.push(...majorRows);
  }

  flushPending();

  return groups.reverse().map((group, index) => ({
    ...group,
    slug: index === 0 ? "changelog" : `changelog-${group.slugPart}`,
    label: index === 0 ? "Changelog" : `Changelog: ${group.rangeLabel}`,
    rowCount: group.rows.length,
    versionedRowCount: group.rows.filter((row) => !row.inferredVersion).length,
    rows: group.rows.map((row) => row.line),
  }));
}

function getChangelogPages(docId) {
  const sourcePath = getSourcePath(docId);
  const source = fs.readFileSync(sourcePath, "utf8");
  const { rows, tableHeader } = parseChangelog(source);
  const connector = docId.split("/").at(-1);
  const title =
    source.match(/^#\s+(.+?)\s*$/m)?.[1] ??
    connector[0].toUpperCase() + connector.slice(1);
  const connectorType = docId.split("/")[0].replace(/s$/, "");

  return groupRows(rows).map((page) => ({
    ...page,
    id: `${docId}/${page.slug}`,
    title,
    connectorType,
    tableHeader,
  }));
}

function renderPage(page, allPages) {
  const heading =
    page.slug === "changelog"
      ? `${page.title} changelog`
      : `${page.title} changelog: ${page.rangeLabel}`;
  const description = `${page.title} ${page.connectorType} connector version history: ${page.rangeLabel}.`;
  const otherPages = allPages.filter((other) => other.slug !== page.slug);
  const otherVersionLinks = otherPages.map(
    (other) => `[${other.rangeLabel}](/integrations/${other.id})`,
  );
  const joinedOtherVersionLinks =
    otherVersionLinks.length > 1
      ? `${otherVersionLinks.slice(0, -1).join(", ")} and ${otherVersionLinks.at(-1)}`
      : otherVersionLinks[0];
  const rendered = [
    "---",
    `title: ${JSON.stringify(heading)}`,
    `sidebar_label: ${JSON.stringify(page.label)}`,
    `description: ${JSON.stringify(description)}`,
    "---",
    "",
    `{/* ${GENERATED_MARKER} from ${page.id.split("/")[1]}.md. Do not edit. */}`,
    "",
    `# ${heading}`,
    "",
    `This page lists changes to the [${page.title} ${page.connectorType} connector](/integrations/${page.id.split("/").slice(0, 2).join("/")}) for ${page.rangeLabel}.`,
    ...(joinedOtherVersionLinks
      ? ["", `For other versions, see ${joinedOtherVersionLinks}.`]
      : []),
    "",
    ...page.tableHeader,
    ...page.rows,
    "",
  ].join("\n");
  if (rendered.includes("undefined")) {
    throw new Error(`Generated changelog page ${page.id} contains undefined.`);
  }
  return rendered;
}

function main() {
  for (const docId of CHANGELOG_PAGE_DOCS) {
    const pages = getChangelogPages(docId);
    const sourcePath = getSourcePath(docId);
    const outputDir = path.join(
      path.dirname(sourcePath),
      path.basename(sourcePath, ".md"),
    );
    const expectedFiles = new Set(pages.map((page) => `${page.slug}.md`));

    fs.mkdirSync(outputDir, { recursive: true });
    for (const fileName of fs.readdirSync(outputDir)) {
      if (!/^changelog.*\.md$/.test(fileName) || expectedFiles.has(fileName)) {
        continue;
      }
      const filePath = path.join(outputDir, fileName);
      let existingContent;
      try {
        existingContent = fs.readFileSync(filePath, "utf8");
      } catch (error) {
        if (error.code === "ENOENT") {
          continue;
        }
        throw error;
      }
      if (!existingContent.includes(GENERATED_MARKER)) {
        continue;
      }
      try {
        fs.unlinkSync(filePath);
      } catch (error) {
        if (error.code !== "ENOENT") {
          throw error;
        }
      }
    }

    for (const page of pages) {
      const filePath = path.join(outputDir, `${page.slug}.md`);
      let existingContent;
      try {
        existingContent = fs.readFileSync(filePath, "utf8");
      } catch (error) {
        if (error.code !== "ENOENT") {
          throw error;
        }
      }
      if (
        existingContent !== undefined &&
        !existingContent.includes(GENERATED_MARKER)
      ) {
        throw new Error(
          `Refusing to overwrite non-generated file: ${filePath}`,
        );
      }
      fs.writeFileSync(filePath, renderPage(page, pages));
      const unversionedRows = page.rowCount - page.versionedRowCount;
      console.log(
        `${filePath}: ${page.versionedRowCount} versioned rows${
          unversionedRows
            ? ` (${page.rowCount} total, including ${unversionedRows} without a version)`
            : ""
        }`,
      );
    }
  }
}

module.exports = {
  CHANGELOG_PAGE_DOCS,
  MAX_ROWS_PER_PAGE,
  getChangelogSourceDocId,
  getChangelogPages,
  isGeneratedChangelogPage,
  main,
};

if (require.main === module) {
  main();
}
